      en: ["Cultural capital.", "Third-largest city in Yemen.", "Known for coffee production.", "Dominated by Mount Sabir."],
      es: ["Capital cultural.", "Tercera ciudad más grande del Yemen.", "Conocida por la producción de café.", "Dominada por el monte Sabir."],
      pt: ["Capital cultural.", "Terceira maior cidade do Iémen.", "Conhecida pela produção de café.", "Dominada pelo Monte Sabir."],
      fr: ["Capitale culturelle.", "Troisième ville du Yémen.", "Réputée pour sa production de café.", "Dominée par le mont Sabir."],
